describe('Live Data Last Updated Timestamp', () => {
  beforeEach(() => {
    cy.visit('/live-data');
  });

  it('should display last updated timestamp for live data', () => {
    // Verify the live data table is visible
    cy.get('[data-testid="live-data-table"]').should('be.visible');

    // Verify the last updated timestamp is displayed
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', 'Last updated');

    // Verify the timestamp format is correct (e.g., YYYY-MM-DD HH:mm:ss)
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', '2023-04-01');

    // Verify the timestamp is within a reasonable range (e.g., not in the future)
    cy.get('[data-testid="last-updated-timestamp"]').then((timestamp) => {
      const now = new Date();
      const lastUpdated = new Date(timestamp);
      expect(lastUpdated).to.be.lte(now);
    });

    // Verify the timestamp is clickable (e.g., opens a modal with more details)
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').click();
    cy.get('[data-testid="update-details-modal"]').should('be.visible');
  });

  it('should handle edge case when no live data is available', () => {
    // Verify the live data table is visible
    cy.get('[data-testid="live-data-table"]').should('be.visible');

    // Verify the last updated timestamp is displayed with a message when no data is available
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', 'No live data available');

    // Verify the timestamp still displays correctly
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', '2023-04-01');

    // Verify the timestamp is still within a reasonable range
    cy.get('[data-testid="last-updated-timestamp"]').then((timestamp) => {
      const now = new Date();
      const lastUpdated = new Date(timestamp);
      expect(lastUpdated).to.be.lte(now);
    });

    // Verify the timestamp is still clickable
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').click();
    cy.get('[data-testid="update-details-modal"]').should('be.visible');
  });
});
